For each $u \in A$ and $t=1,\dots,T$ we have:
\begin{equation*}
    P \left( \underset{t= 1,\dots, T}{\forall} \, \underset{u \in A}{\forall} \left | \sum_{i \in S_t^u} \epsilon_i \right| \le \sqrt{\xi_t |S_t^u|} \right) \ge 1 - \delta_B ,
\end{equation*}
where $\xi_t = 2 \sigma_N^2 \log \frac{|A|\pi^2 t^2}{6\delta_B}$.

Let $f \in \mathcal{H}\left(k^{\theta}\right)$, such that $\lVert f \rVert_{k^{\theta}} \le B$ and set $\beta_t^{\theta, B} = B + \sigma_N \sqrt{2 (\mathcal{I}_{t-1}(k^{\theta}) + 1 + \ln (1/\delta_A))}$, where $\mathcal{I}_T(k^\theta)$ is an upper bound  $\frac{1}{2} \log \lvert I + \sigma_N^{-2} \bm{K}^{\theta^\star}_T \rvert \le \mathcal{I}_T(k^\theta)$, which depends on the kernel and length scale choice. 
Then, with probability at least $1 - \delta_A$, for all $\bm{x} \in \mathcal{X}$ and $t = 1, \dots, T$:
    \begin{equation*}
    \left|f(\bm{x}) -  \mu_{t-1}^{\theta}(\bm{x})\right| \le \beta_t^{\theta, B} \sigma_{t-1}^{\theta} (\bm{x}) .
\end{equation*}

Assume the event of Lemma B.3 holds.
Let us call by $\mathcal{T}$ the set of all iterations after $t_0$, where we do not reject any of the candidates. We must have that for any $u \in A$:
\begin{align*}
\sum_{\substack{t \notin \mathcal{T} \\     t \in S_T^{u}}} r_t
 & \le \left(\frac{|S_T^{u}|}{|S_T^{u^*}|} + 1 \right) CR^{u^\star}(|S_T^{u^*}|) + 2CB^{u^\star} + 2\left(\sqrt{\frac{|S_T^{u}|}{|S_T^{u^*}|}} + 1\right)\sqrt{|S_T^{u}|\xi_t} .
\end{align*}

Let us run Algorithm alg:hb_bo for $T$ iterations with a given choice of the hyperparameter-proposing function $a: \mathbb{N} \to \mathcal{U}$. Let $\mathcal{T}$ be the set of all iterations after $t_0$, where at least one hyperparameter is rejected by operation in line 11. If we set $\xi_t = 2 \sigma_N^2 \log \frac{|A|\pi^2 t^2}{6\delta_B}$ and $\beta^{u}_t = B^u + \sigma_N \sqrt{2 (\gamma^{u}_{t-1} + 1 + \ln (1/\delta_A))}$, we then have that with probability as least $1 - \delta_A - \delta_B$:
    \begin{equation*}
\sum_{t \notin \mathcal{T}} r_t = \mathcal{O} \left(|A|B^{u^\star} + \left(R^{u^*}(T) + \sqrt{T\xi_T}  \right) \left(\sum_{u \in \mathcal{M}_0}\sqrt{\frac{|S_t^{u}|}{|S_{t^\prime}^{u^\star}|}} + |A| \right) \right) .
\end{equation*}
